pub fn find_thumb(filename_or_key: &str) -> Option<&'static ThumbEntry> {
    let key = if filename_or_key == "default" || filename_or_key == "Default" {
        "wallpaper.jpg"
    } else {
        filename_or_key.rsplit('/').next().unwrap_or(filename_or_key)
    };
    THUMBS.iter().find(|t| t.filename == key)
}
